import {
  Activity,
  Captions,
  CodeXml,
  GalleryHorizontal,
  Layers,
  MonitorPlay,
  Radio,
  Settings,
  type LucideIcon,
} from 'lucide-react'
import type { VideoGlossaryTerm } from '@/lib/videos/glossary'

export type VideoTab =
  | 'overview'
  | 'renditions'
  | 'subtitles'
  | 'timeline'
  | 'streaming'
  | 'install'
  | 'settings'

export type VideoTabGroup = 'video' | 'encoding' | 'delivery' | 'manage'

export type VideoTabDefinition = {
  id: VideoTab
  label: string
  icon: LucideIcon
  group: VideoTabGroup
  term?: VideoGlossaryTerm
}

/** Order here is the order of the submenu and the context menu. */
export const VIDEO_TABS: VideoTabDefinition[] = [
  { id: 'overview', label: 'Overview', icon: MonitorPlay, group: 'video' },
  {
    id: 'renditions',
    label: 'Renditions',
    icon: Layers,
    group: 'encoding',
    term: 'rendition',
  },
  {
    id: 'subtitles',
    label: 'Subtitles',
    icon: Captions,
    group: 'encoding',
  },
  {
    id: 'timeline',
    label: 'Timeline',
    icon: GalleryHorizontal,
    group: 'encoding',
    term: 'timeline',
  },
  {
    id: 'streaming',
    label: 'Streaming',
    icon: Radio,
    group: 'delivery',
    term: 'manifest',
  },
  { id: 'install', label: 'Install', icon: CodeXml, group: 'delivery' },
  { id: 'settings', label: 'Settings', icon: Settings, group: 'manage' },
]

/** Opens the inspector window; listed after the Playback tabs. */
export const VIDEO_INSPECTOR_ACTION = {
  label: 'Inspector',
  icon: Activity,
  group: 'delivery',
} as const satisfies Omit<VideoTabDefinition, 'id'>

export const VIDEO_TAB_GROUP_LABELS: Record<VideoTabGroup, string | null> = {
  video: null,
  encoding: 'Media',
  delivery: 'Playback',
  manage: null,
}

export const VIDEO_TAB_NEEDS_READY_RENDITION =
  'Available once a rendition is ready.'

/** English reason a tab can't be opened yet, or null when it is available. */
export function getVideoTabDisabledReason(
  tab: VideoTab,
  renditions: { status: string }[],
): string | null {
  if (tab !== 'streaming') return null
  return renditions.some((r) => r.status === 'ready')
    ? null
    : VIDEO_TAB_NEEDS_READY_RENDITION
}

export function videoTabPath(tab: VideoTab) {
  return (
    tab === 'overview'
      ? '/projects/$projectId/videos/$videoId'
      : `/projects/$projectId/videos/$videoId/${tab}`
  ) as '/projects/$projectId/videos/$videoId'
}
import { useCallback, useEffect, useRef, useState } from 'react'

type PopoutOptions = {
  title?: string
  width?: number
  /** Fraction of the current screen's available width; overrides `width`. */
  widthRatio?: number
  height?: number
  onBlocked?: () => void
}

function isStyleNode(node: Node): node is HTMLStyleElement | HTMLLinkElement {
  return (
    node instanceof HTMLStyleElement ||
    (node instanceof HTMLLinkElement && node.rel === 'stylesheet')
  )
}

function mirrorRootAttributes(target: Document) {
  const { documentElement: from, body } = document
  target.documentElement.className = from.className
  target.documentElement.setAttribute('style', from.getAttribute('style') ?? '')
  target.documentElement.dir = from.dir
  target.documentElement.lang = from.lang
  target.body.className = body.className
}

type DocumentPictureInPicture = {
  requestWindow: (options: { width: number; height: number }) => Promise<Window>
}

/**
 * Chrome turns `window.open` popups into tabs while the browser is in macOS
 * full screen. Document Picture-in-Picture still gets a separate window there,
 * though Chrome caps its initial size (the user can resize it).
 */
async function openChildWindow(w: number, h: number): Promise<Window | null> {
  const pip = (
    window as Window & { documentPictureInPicture?: DocumentPictureInPicture }
  ).documentPictureInPicture
  if (pip && window.matchMedia('(display-mode: fullscreen)').matches) {
    try {
      return await pip.requestWindow({ width: w, height: h })
    } catch {
      // Fall through to a regular popup.
    }
  }
  const screen = window.screen as Screen & {
    availLeft?: number
    availTop?: number
  }
  const minLeft = screen.availLeft ?? 0
  const minTop = screen.availTop ?? 0
  const left = Math.round(
    Math.min(
      Math.max(window.screenX + (window.outerWidth - w) / 2, minLeft),
      minLeft + screen.availWidth - w,
    ),
  )
  const top = Math.round(
    Math.min(
      Math.max(window.screenY + (window.outerHeight - h) / 2, minTop),
      minTop + screen.availHeight - h,
    ),
  )
  return window.open(
    'about:blank',
    '_blank',
    [
      'popup=yes',
      `width=${w}`,
      `height=${h}`,
      `left=${left}`,
      `top=${top}`,
      'toolbar=no',
      'location=no',
      'menubar=no',
      'status=no',
      'scrollbars=yes',
      'resizable=yes',
    ].join(','),
  )
}

/**
 * Opens a same-origin child window and returns a container element inside it.
 * Render into it with `createPortal`: the content stays in this React tree, so
 * both windows share state, context, and callbacks without any messaging.
 */
export function usePopoutWindow({
  title,
  width = 1360,
  widthRatio,
  height = 880,
  onBlocked,
}: PopoutOptions) {
  const [container, setContainer] = useState<HTMLElement | null>(null)
  const windowRef = useRef<Window | null>(null)
  const cleanupRef = useRef<(() => void) | null>(null)

  const close = useCallback(() => {
    cleanupRef.current?.()
    cleanupRef.current = null
    windowRef.current?.close()
    windowRef.current = null
    setContainer(null)
  }, [])

  const open = useCallback(
    async (titleOverride?: string) => {
      if (windowRef.current && !windowRef.current.closed) {
        if (titleOverride) windowRef.current.document.title = titleOverride
        windowRef.current.focus()
        return
      }
      const w = widthRatio
        ? Math.round(window.screen.availWidth * widthRatio)
        : Math.min(width, window.screen.availWidth)
      const h = Math.min(height, window.screen.availHeight)
      const popup = await openChildWindow(w, h)
      if (!popup) {
        onBlocked?.()
        return
      }
      windowRef.current = popup

      const doc = popup.document
      doc.title = titleOverride ?? title ?? ''
      doc.head.replaceChildren()
      doc.body.replaceChildren()
      for (const node of Array.from(document.head.childNodes)) {
        if (isStyleNode(node)) doc.head.appendChild(node.cloneNode(true))
      }
      mirrorRootAttributes(doc)

      const root = doc.createElement('div')
      root.className = 'h-full'
      doc.body.style.margin = '0'
      doc.body.style.height = '100%'
      doc.documentElement.style.height = '100%'
      doc.body.appendChild(root)

      // Keep styles (dev HMR) and theme / direction in sync with the main window.
      const headObserver = new MutationObserver((mutations) => {
        for (const mutation of mutations) {
          for (const node of Array.from(mutation.addedNodes)) {
            if (isStyleNode(node)) doc.head.appendChild(node.cloneNode(true))
          }
        }
      })
      headObserver.observe(document.head, { childList: true })
      const rootObserver = new MutationObserver(() => {
        mirrorRootAttributes(doc)
        doc.body.style.margin = '0'
        doc.body.style.height = '100%'
        doc.documentElement.style.height = '100%'
      })
      rootObserver.observe(document.documentElement, { attributes: true })
      rootObserver.observe(document.body, { attributes: true })

      const handlePopupClose = () => {
        cleanupRef.current?.()
        cleanupRef.current = null
        windowRef.current = null
        setContainer(null)
      }
      popup.addEventListener('pagehide', handlePopupClose)
      const handleMainUnload = () => popup.close()
      window.addEventListener('pagehide', handleMainUnload)

      cleanupRef.current = () => {
        headObserver.disconnect()
        rootObserver.disconnect()
        popup.removeEventListener('pagehide', handlePopupClose)
        window.removeEventListener('pagehide', handleMainUnload)
      }
      setContainer(root)
    },
    [title, width, widthRatio, height, onBlocked],
  )

  useEffect(() => close, [close])

  return { container, open, close, isOpen: container != null }
}
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { useNavigate } from '@tanstack/react-router'
import { Activity } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { useT } from '@/lib/i18n/translate'
import { usePopoutWindow } from './usePopoutWindow'

type OpenInspectorOptions = {
  projectId: string
  videoId: string
  videoName: string
}

type VideoInspectorValue = {
  /** Element inside the inspector window to portal into; `null` while closed. */
  container: HTMLElement | null
  isOpen: boolean
  open: (options: OpenInspectorOptions) => void
  close: () => void
  /** Called by a mounted player; returns the detach function. */
  attach: () => () => void
}

const VideoInspectorContext = createContext<VideoInspectorValue | null>(null)

export function useVideoInspector() {
  return useContext(VideoInspectorContext)
}

export function inspectorWindowTitle(videoName: string, suffix: string) {
  return videoName ? `${videoName} · ${suffix}` : suffix
}

/**
 * Owns the inspector pop-up for the videos workspace. The window has to
 * open from the click itself (pop-up blockers), so menus open it here and the
 * player on the Overview page renders into it once mounted.
 */
export function VideoInspectorProvider({ children }: { children: ReactNode }) {
  const t = useT()
  const navigate = useNavigate()
  const [attached, setAttached] = useState(0)
  const [target, setTarget] = useState<OpenInspectorOptions | null>(null)

  const onBlocked = useCallback(() => {
    toast.error(
      t(
        'Your browser blocked the window. Allow pop-ups for this site to open the inspector.',
      ),
    )
  }, [t])
  const popout = usePopoutWindow({ onBlocked, widthRatio: 1 })
  const { open: openWindow, close, container } = popout

  const open = useCallback(
    (options: OpenInspectorOptions) => {
      setTarget(options)
      void openWindow(inspectorWindowTitle(options.videoName, t('Inspector')))
    },
    [openWindow, t],
  )

  const attach = useCallback(() => {
    setAttached((count) => count + 1)
    return () => setAttached((count) => count - 1)
  }, [])

  const value = useMemo<VideoInspectorValue>(
    () => ({ container, isOpen: popout.isOpen, open, close, attach }),
    [container, popout.isOpen, open, close, attach],
  )

  const goToOverview = () => {
    if (!target) return
    window.focus()
    void navigate({
      to: '/projects/$projectId/videos/$videoId',
      params: { projectId: target.projectId, videoId: target.videoId },
    })
  }

  return (
    <VideoInspectorContext.Provider value={value}>
      {children}
      {container && attached === 0
        ? createPortal(
            <div className="flex h-full items-center justify-center bg-background p-6 text-foreground">
              <div className="max-w-sm text-center">
                <span className="mx-auto flex size-10 items-center justify-center rounded-lg bg-muted text-muted-foreground">
                  <Activity className="h-5 w-5" />
                </span>
                <h2 className="mt-4 text-[15px] font-semibold">
                  {t('Waiting for the player')}
                </h2>
                <p className="mt-2 text-[13px] text-muted-foreground">
                  {t(
                    "The inspector follows the video playing on a video's Overview page. Open one to continue inspecting.",
                  )}
                </p>
                <div className="mt-4 flex justify-center gap-2">
                  {target ? (
                    <Button
                      type="button"
                      size="sm"
                      className="h-8 text-[13px]"
                      onClick={goToOverview}
                    >
                      {t('Go to overview')}
                    </Button>
                  ) : null}
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    className="h-8 text-[13px]"
                    onClick={close}
                  >
                    {t('Close')}
                  </Button>
                </div>
              </div>
            </div>,
            container,
          )
        : null}
    </VideoInspectorContext.Provider>
  )
}
